using Astronomy.MediaFactory.Core.KnowledgeFoundation;using Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Integration;using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogBuilderTests{[Fact]public void KnowledgeCatalogBuilder_maps_actual_production_metadata_deterministically(){var s=KnowledgeCatalogFixture.Catalog().Snapshot;Assert.Equal(Enum.GetValues<AstronomyKnowledgeDomain>().Length,s.Domains.Count);Assert.Equal(Enum.GetValues<AstronomyKnowledgePayloadFamily>().Length,s.PayloadFamilies.Count);Assert.Equal(AstronomyBuiltInTypedPayloadDescriptors.BuiltIn.Count,s.KnowledgeTypes.Count);Assert.Equal(Enum.GetValues<KnowledgeStatementKind>().Length,s.StatementKinds.Count);Assert.Contains(s.Domains,e=>e.Code=="classification");Assert.Contains(s.PayloadFamilies,e=>e.Code=="entity-classification");Assert.Contains(s.KnowledgeTypes,e=>e.Code=="typed.classification.entity.v1");Assert.True(s.ValidationRules.Count>0);Assert.True(s.CrossDomainValidationRules.Count>0);Assert.Equal(11,s.GraphValidationRules.Count);var s2=KnowledgeCatalogFixture.Catalog().Snapshot;Assert.Equal(s.Entries.Select(e=>e.Id),s2.Entries.Select(e=>e.Id));}}
